head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onbeforetoggleclick]<br/>inputType='drilldown' 인 Body Cell 에서 토글 버튼을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "ignoreCellClick=true 일때 onbeforetoggleclick 이벤트의 반환값이 true 이면 oncellclick 이벤트가 발생하지 않습니다.",
        "ignoreToggleOnDisabled 속성값에 따라 disabled 상태인 Body Cell 에서도 onbeforetoggleclick 이벤트가 발생할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 — DrillDown(부모+Leaf) 그리드 + onbeforetoggleclick/ontoggleclick/oncellclick 바인딩
//  - name 컬럼을 inputType="drilldown" + depthColumn="depth" + showDepth="1" + depthStartIndex="1"
//  - 부모 Row(개발본부)의 이름 셀은 setCellDisabled 로 disabled 적용 → ignoreToggleOnDisabled 검증용
//  - con_ignoreCellClick / con_ignoreToggleOnDisabled : @spec 검증용 con (미설정/true/false)
//  - onbeforetoggleclick 은 항상 true 반환(ignoreCellClick 검증 전제: 반환값 true 일 때 oncellclick 미발생)
scwin.gVar = { logArr: [] };

scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_bind !== 'undefined') { $p.data.remove("dlt_bind"); }

    scwin.gVar.logArr = [];

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="DrillDown 그리드(본부>팀>사원). 개발본부 이름셀만 disabled. [ignoreCellClick 검증] 영업본부(enable) 토글 클릭 → 순서로그에서 oncellclick 발생 여부 확인(true=미발생/false=발생). [ignoreToggleOnDisabled 검증] 개발본부(disabled) 토글 클릭 → onbeforetoggleclick 발생 여부 확인(true=미발생/false=발생). onbeforetoggleclick 은 항상 true 반환. con 변경 후 [Target 재생성]."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 부모(자식 보유)와 Leaf(자식 없음)를 모두 포함
    let jsonData = [
        { "name": "영업본부",   "dept": "Sales", "depth": 1 },
        { "name": "영업1팀",    "dept": "Sales", "depth": 2 },
        { "name": "김영업",     "dept": "Sales", "depth": 3 },
        { "name": "이영업",     "dept": "Sales", "depth": 3 },
        { "name": "개발본부",   "dept": "Dev",   "depth": 1 },
        { "name": "개발1팀",    "dept": "Dev",   "depth": 2 },
        { "name": "박개발",     "dept": "Dev",   "depth": 3 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 값 수집 — 미설정이면 빈문자(속성 미적용)
    //  - gdl_boolean 바인딩 셀렉트(ignoreCellClick/ignoreToggleOnDisabled)는 value 가 1/2/3 이므로 getText()로 ""/true/false 취득
    //    (getValue 로 읽으면 value 1/2/3 이 그대로 전달돼 속성이 미적용되는 결함이 있었음)
    let properties = { dataList: "data:dlt_bind" };
    let ignoreCellClick = con_ignoreCellClick.getText();
    let ignoreToggleOnDisabled = con_ignoreToggleOnDisabled.getText();
    if (ignoreCellClick !== "") { properties.ignoreCellClick = ignoreCellClick; }
    if (ignoreToggleOnDisabled !== "") { properties.ignoreToggleOnDisabled = ignoreToggleOnDisabled; }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbeforetoggleclick", "ontoggleclick", "oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:280px;" ' + eList + '>';
    strTarget += '<w2:caption style="" id="caption1" value="onbeforetoggleclick DrillDown 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol1" value="이름(DrillDown)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="depth" dataList="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 부모 Row(개발본부)의 이름(drilldown) 셀을 disabled 적용 → ignoreToggleOnDisabled 검증용
    //  - DrillDown 은 자식 접힘 상태라 표시 Row(0:영업본부, 1:개발본부)와 실제 데이터 Row 가 다름
    //  - setCellDisabled 는 실제 데이터 Row 인덱스 기준이어야 클릭 경로의 _getEditDisabled 가 인식 → 개발본부=실제 4
    //  - 영업본부(표시0)는 enable 유지 → ignoreCellClick 검증(토글 정상 동작)용
    scwin.target1.setCellDisabled(4, "name", true);
};



// [onbeforetoggleclick] : 토글 버튼 클릭으로 발생. 토글 동작 전. 항상 true 반환(ignoreCellClick 검증 전제).
scwin.target1_onbeforetoggleclick = function (rowIndex) {
    let b = wf_body_bottom.getObj("scwin");
    b.btn_clear_onclick();
    scwin.gVar.logArr = [];

    scwin.gVar.logArr.push("onbeforetoggleclick");

    b.setReturnValue("===== target1_onbeforetoggleclick =====");
    b.setReturnValue("rowIndex(payload) : " + rowIndex);
    b.setReturnValue("반환값 : true (ignoreCellClick 검증 전제)");

    return true;
};



// [ontoggleclick] : onbeforetoggleclick 가 true 일 때 이어서 발생.
scwin.target1_ontoggleclick = function (collapsed, rowIndex) {
    let b = wf_body_bottom.getObj("scwin");
    scwin.gVar.logArr.push("ontoggleclick");

    b.setReturnValue("----- target1_ontoggleclick -----");
    b.setReturnValue("rowIndex(payload) : " + rowIndex);
};



// [oncellclick] : ignoreCellClick=false/미설정 이면 토글 클릭 시 발생, true 이면 미발생
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let b = wf_body_bottom.getObj("scwin");
    scwin.gVar.logArr.push("oncellclick");

    b.setReturnValue("----- target1_oncellclick -----");
    b.setReturnValue("rowIndex(payload) : " + rowIndex + " , columnId : " + columnId);
    // 이벤트 발생 순서 누적 로그 출력 → ignoreCellClick=true 면 oncellclick 이 빠짐
    b.setReturnValue("[이벤트 발생 순서] " + scwin.gVar.logArr.join(" > "));
};
